import {useEffect,useRef,useState} from 'react';
import {Bell,ChevronDown,Volume2,VolumeX,X} from 'lucide-react';
import ImageUpload from './ImageUpload';
import {Field,Form} from './ui';
import {platform,useResource,timestamp} from './data';
export function Feedback({resource}){return resource.loading?<p role="status" className="muted">Loading your workspace…</p>:resource.error?<div role="alert" className="error">{resource.error}<button className="text-button" onClick={resource.refresh}>Try again</button></div>:null;}
export function Blank({title,children}){return <div className="blank"><h3>{title}</h3>{children?<p>{children}</p>:null}</div>;}
export function Section({title,children,action}){return <section className="platform-section"><div className="section-heading"><h2>{title}</h2>{action}</div>{children}</section>;}
export function QR({token,label}){const [source,setSource]=useState('');useEffect(()=>{let active=true;import('qrcode').then(m=>m.toDataURL(token,{width:220,margin:1})).then(value=>{if(active)setSource(value);});return()=>{active=false;};},[token]);return <div className="qr-display"><h3>{label}</h3>{source?<img src={source} width="220" height="220" alt={label}/>:<p>Preparing QR…</p>}<details><summary>Manual fallback token</summary><code className="secret">{token}</code></details></div>;}
export function Scanner({onScan}){const [active,setActive]=useState(false),[error,setError]=useState('');const video=useRef();useEffect(()=>{if(!active)return;let stream,cancelled=false,timer;const stop=()=>{clearTimeout(timer);stream?.getTracks().forEach(t=>t.stop());};(async()=>{try{if(!window.BarcodeDetector)throw new Error('Camera QR decoding is unavailable in this browser. Use the manual token below.');const detector=new window.BarcodeDetector({formats:['qr_code']});stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false});if(cancelled){stop();return;}video.current.srcObject=stream;await video.current.play();const detect=async()=>{if(cancelled)return;try{const codes=await detector.detect(video.current);if(codes.length){await onScan(codes[0].rawValue);setActive(false);return;}}catch(e){setError(e.message);}timer=setTimeout(detect,400);};void detect();}catch(e){setError(e.message);setActive(false);}})();return()=>{cancelled=true;stop();};},[active,onScan]);return <><button type="button" className="secondary" onClick={()=>{setError('');setActive(!active);}}>{active?'Stop camera':'Scan QR with camera'}</button>{active?<video ref={video} className="scan-video" muted playsInline aria-label="QR scanner camera"/>:null}{error?<p role="alert" className="error">{error}</p>:null}</>;}
export function Profile(){const r=useResource(()=>platform('/profile'));return <><h1>Your public profile.</h1><p className="muted">Choose the photo and name customers see in the community.</p><Feedback resource={r}/>{r.data?<div className="form-panel"><div className="profile-avatar">{r.data.profile?.avatar?<img src={r.data.profile.avatar} alt="Your profile"/>:<span>{(r.data.profile?.display_name??'D').slice(0,1)}</span>}</div><Form key={JSON.stringify(r.data)} submit="Save profile" onSubmit={async d=>{await platform('/profile','PATCH',d);await r.refresh();}}><ImageUpload label="Profile photo" name="avatar" value={r.data.profile?.avatar}/><Field label="Public display name" name="name" required maxLength={100} defaultValue={r.data.profile?.display_name??''}/></Form><p className="small muted">Phone number: {r.data.profile?.phone||'Not provided at registration'}</p></div>:null}</>;}
export function Notifications(){const r=useResource(()=>platform('/notifications'));return <><h1>Your updates.</h1><AlertSettings/><Feedback resource={r}/>{r.data?<Section title="Notifications" action={<button className="secondary" onClick={r.refresh}>Refresh</button>}>{r.data.notifications.length?<ul className="event-list">{r.data.notifications.map(n=><li key={n.id}><strong>{n.message}</strong><small>{timestamp(n.created_at)}</small></li>)}</ul>:<Blank title="You're all caught up.">Verification and operational updates appear here.</Blank>}</Section>:null}</>;}
export function Addresses(){const r=useResource(()=>platform('/addresses'));return <><h1>Every destination, saved.</h1><p className="muted">Your delivery addresses stay private to your orders.</p><Feedback resource={r}/>{r.data?<Section title="Saved addresses">{r.data.addresses.length?<ul className="event-list">{r.data.addresses.map(a=><li key={a.id}><strong>{a.label}</strong><p>{a.address}</p><small>{a.country}</small></li>)}</ul>:<Blank title="No addresses yet.">Add a delivery destination below.</Blank>}</Section>:null}<div className="form-panel"><h2>Add an address</h2><Form submit="Save address" onSubmit={async d=>{await platform('/addresses','POST',{...d,country:d.country.toUpperCase()});await r.refresh();}}><Field label="Label" name="label" required maxLength={60} placeholder="Home or workplace"/><Field label="Delivery address"><textarea name="address" required maxLength={1000}/></Field><Field label="Country code" name="country" required pattern="[A-Za-z]{2}" maxLength={2} placeholder="NG"/></Form></div></>;}

export function AlertSettings(){const r=useResource(()=>platform('/notification-preferences')),[notice,setNotice]=useState('');return <div className="service-panel"><h2>Transaction and security alerts</h2><p>Browser alerts can appear while DEN is running. Your browser and operating system quiet settings still apply; web pages cannot override Do Not Disturb.</p><Feedback resource={r}/>{r.data?<button className="secondary" onClick={async()=>{try{let enabled=!r.data.browserAlerts;if(enabled){if(!('Notification' in window))throw Error('Browser notifications are unavailable.');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Allow notifications in your browser settings first.');}await platform('/notification-preferences','PATCH',{browserAlerts:enabled});await r.refresh();setNotice(enabled?'Browser alerts enabled.':'Browser alerts disabled.');}catch(e){setNotice(e.message);}}}>{r.data.browserAlerts?'Disable browser alerts':'Enable browser alerts'}</button>:null}{notice?<p role="status">{notice}</p>:null}</div>;}
export function useBrowserAlerts(userId,role){useEffect(()=>{if(role==='manager'||role==='rider')return;let cancelled=false,seen=null;const check=async()=>{try{if(!userId||document.hidden)return;const prefs=await platform('/notification-preferences');if(!prefs.browserAlerts||!('Notification' in window)||Notification.permission!=='granted')return;const data=await platform('/notifications');if(cancelled)return;const next=new Set(data.notifications.map(n=>n.id));if(seen)for(const n of data.notifications.filter(n=>!seen.has(n.id)).slice(0,3))new Notification('DEN Global',{body:n.message,tag:n.id});seen=next;}catch{}};void check();const timer=setInterval(check,20000);return()=>{cancelled=true;clearInterval(timer);};},[userId,role]);}
export async function clearPetPush(){const registration=await navigator.serviceWorker?.getRegistration('/'),subscription=await registration?.pushManager.getSubscription();if(subscription){try{await platform('/push/subscriptions','DELETE',{endpoint:subscription.endpoint});}finally{await subscription.unsubscribe().catch(()=>{});}}}

const petPrefsKey=userId=>`den.pet-alerts.${userId}`;
function readPetPrefs(userId){try{return{voice:false,...JSON.parse(localStorage.getItem(petPrefsKey(userId))||'{}')};}catch{return{voice:false};}}
function PetMascot(){return <img className="pet-mascot" src="/den-pet-icon.jpg" alt="" aria-hidden="true"/>;}
export function PetCompanion({userId,role}){
 const [settings,setSettings]=useState(()=>readPetPrefs(userId)),[open,setOpen]=useState(false),[alert,setAlert]=useState(null),[browserAlerts,setBrowserAlerts]=useState(false),[quietNote,setQuietNote]=useState(''),[pushEnabled,setPushEnabled]=useState(false),[pushBusy,setPushBusy]=useState(false),[pushNote,setPushNote]=useState('');
 useEffect(()=>{setSettings(readPetPrefs(userId));},[userId]);
 useEffect(()=>{try{localStorage.setItem(petPrefsKey(userId),JSON.stringify(settings));}catch{}},[settings,userId]);
 useEffect(()=>{let active=true;(async()=>{try{const [server,registration]=await Promise.all([platform('/push/subscriptions'),navigator.serviceWorker?.getRegistration('/')]);const subscription=await registration?.pushManager.getSubscription();if(active)setPushEnabled(Boolean(server.enabled&&subscription));}catch{}})();return()=>{active=false;};},[userId]);
 const togglePush=async()=>{setPushBusy(true);setPushNote('');try{if(pushEnabled){const registration=await navigator.serviceWorker.getRegistration('/'),subscription=await registration?.pushManager.getSubscription();if(subscription){await platform('/push/subscriptions','DELETE',{endpoint:subscription.endpoint});await subscription.unsubscribe();}setPushEnabled(false);setPushNote('Background alerts are off.');return;}if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window))throw Error('This browser does not support background alerts.');const config=await platform('/push/config');if(!config.enabled)throw Error('Background push is not configured on this DEN server yet.');if(Notification.permission!=='granted'){const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Allow notifications in browser settings to continue.');}const registration=await navigator.serviceWorker.register('/den-push-sw.js');let subscription=await registration.pushManager.getSubscription();const padded=config.publicKey+'='.repeat((4-config.publicKey.length%4)%4),key=Uint8Array.from(atob(padded.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0)),currentKey=subscription?.options.applicationServerKey;if(subscription&&(!currentKey||currentKey.byteLength!==key.byteLength||new Uint8Array(currentKey).some((b,i)=>b!==key[i]))){await platform('/push/subscriptions','DELETE',{endpoint:subscription.endpoint});await subscription.unsubscribe();subscription=null;}if(!subscription)subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});await platform('/push/subscriptions','POST',subscription.toJSON());setPushEnabled(true);setPushNote('Background alerts are on. Your device still controls quiet settings.');}catch(e){setPushNote(e.message||'Could not enable background alerts.');}finally{setPushBusy(false);}};
 useEffect(()=>{if(settings.active===false)return;let cancelled=false,seen=null;try{const saved=localStorage.getItem(`den.pet-seen.${userId}`);if(saved)seen=new Set(JSON.parse(saved));}catch{}const poll=async()=>{try{const [data,prefs]=await Promise.all([platform('/notifications'),platform('/notification-preferences')]);if(cancelled)return;setBrowserAlerts(Boolean(prefs.browserAlerts));const current=Array.isArray(data.notifications)?data.notifications:[],ids=new Set(current.map(n=>n.id));if(seen){const fresh=current.filter(n=>!seen.has(n.id)).reverse();for(const item of fresh.slice(0,3)){setAlert(item);setOpen(true);if(settings.voice&&'speechSynthesis'in window&&!document.hidden&&document.hasFocus()){const speech=new SpeechSynthesisUtterance(item.message);speech.rate=.96;speech.pitch=1.08;window.speechSynthesis.cancel();window.speechSynthesis.speak(speech);}if(!pushEnabled&&prefs.browserAlerts&&'Notification'in window&&Notification.permission==='granted'&&(document.hidden||!document.hasFocus()))new Notification('DEN · '+(role==='manager'?'Store update':'Rider update'),{body:item.message,tag:item.id});}}seen=ids;try{localStorage.setItem(`den.pet-seen.${userId}`,JSON.stringify([...ids].slice(0,100)));}catch{}}catch{}};void poll();const timer=setInterval(()=>void poll(),18000);return()=>{cancelled=true;clearInterval(timer);};},[userId,role,settings.voice,settings.active,pushEnabled]);
 if(!userId||settings.active===false)return <button className="pet-reopen" onClick={()=>setSettings(current=>({...current,active:true}))} aria-label="Show pet notification companion"><PetMascot/><span>Alerts off</span></button>;
 return <aside className={`pet-companion ${open?'is-open':'is-closed'}`} aria-label="DEN pet notification companion">
  {open?<section className="pet-alert-card"><header><div className="pet-card-identity"><PetMascot/><div><strong>DEN companion</strong><small>{role==='manager'?'Store helper':'Rider helper'}</small></div></div><button className="pet-icon-button" onClick={()=>setOpen(false)} aria-label="Minimize companion"><ChevronDown size={17}/></button></header>
   <div className="pet-alert-message" aria-live="polite">{alert?<><span className="pet-event-kicker"><Bell size={13}/>{role==='manager'?'Order update':'Delivery update'}</span><p>{alert.message}</p><small>{new Date(alert.created_at??alert.createdAt).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}</small></>:<><span className="pet-event-kicker">HERE WITH YOU</span><p>{role==='manager'?'I’ll let you know when a new customer order arrives.':'I’ll let you know when a delivery order is available.'}</p></>}</div>
   <div className="pet-controls"><button className="pet-voice-toggle" aria-pressed={settings.voice} onClick={()=>setSettings(current=>({...current,voice:!current.voice}))}>{settings.voice?<Volume2 size={15}/>:<VolumeX size={15}/>} Voice {settings.voice?'on':'off'}</button><button className="pet-quiet-toggle" onClick={()=>setQuietNote(current=>current?'':'Browser alerts follow your operating system’s Do Not Disturb settings.')}>Quiet hours info</button><button className="pet-icon-button" onClick={()=>{setSettings(current=>({...current,active:false}));window.speechSynthesis?.cancel?.();}} aria-label="Turn companion off"><X size={15}/></button></div>
   <div className="pet-push-row"><button className="pet-voice-toggle" onClick={togglePush} disabled={pushBusy}>{pushBusy?'Updating…':pushEnabled?'Turn off background alerts':'Enable background alerts'}</button><span>{pushNote||'Get a device popup while DEN is closed.'}</span></div>
   {quietNote?<p className="pet-quiet-note" role="status">{quietNote}</p>:null}
   {browserAlerts&&typeof Notification!=='undefined'&&Notification.permission!=='granted'?<p className="pet-quiet-note">Desktop popups are enabled in DEN settings but browser permission is still needed. Enable it from Notifications.</p>:null}
  </section>:null}
  <button className="pet-orb" onClick={()=>setOpen(current=>!current)} aria-label={open?'Hide pet companion':'Show pet companion'}><PetMascot/><span className="pet-status-dot"/></button>
 </aside>;
}
